// The Antitheft app's own alert card for the demo attack, for docs/screenshots/overview.png. It imports the app's
// UI (the private antitheft repo's ui/src), so it runs from there: copy this file to ui/src/ and shots-popup.html to
// ui/, run `npx vite --port 1499`, take http://localhost:1499/shots-popup.html with headless Chrome at 2x on a
// transparent background (--force-device-scale-factor=2 --window-size=452,640 --default-background-color=00000000),
// crop to the card, overlay it on alerts.png bottom-right (ffmpeg overlay=x=W-w-56:y=H-h-96), delete the copies.
import { createRoot } from "react-dom/client"
import "./index.css"
import "@/pages/Home.css"
import { AlertNotification } from "@/components/notification/AlertNotification"
import { alertFromRun } from "@/components/notification/alertFromRaw"
import type { AlertEvent } from "@/lib/agent"

// the daemon's icon route, answered here with the icon antitheft serves for Chrome (the demo has no daemon)
const ICONS: Record<string, string> = { chrome: "{\"content_type\":\"image/png\",\"data_base64\":\"\",\"resource_id\":\"chrome\"}" }
const realFetch = window.fetch.bind(window)
window.fetch = async (input: RequestInfo | URL, init?: RequestInit) => {
  const url = String(input)
  const m = url.match(/\/api\/v1\/icon\/([^/?]+)$/)
  if (m && ICONS[decodeURIComponent(m[1])]) return new Response(ICONS[decodeURIComponent(m[1])], { status: 200, headers: { "content-type": "application/json" } })
  if (url.startsWith("http://127.0.0.1:4091")) return new Response("{}", { status: 404, headers: { "content-type": "application/json" } })
  return realFetch(input, init)
}
document.documentElement.classList.add("dark", "notification-window")
const now = Math.floor(Date.now() / 1000)
const program = { pid: 4242, parent_pid: 3301, image_path: "/home/dev/.cache/claude-code-assistant/claude-helper", app: "claude-helper", cmdline: "/home/dev/.cache/claude-code-assistant/claude-helper --silent" }
const chain = [{ pid: 3301, parent_pid: 3200, image_path: "/usr/share/codium/codium", app: "VSCodium", title_id: "vscodium", role: "editor" }]
const raws: AlertEvent[] = [
  { id: 4108, reviewed: false, count: 3, paused: false, kind: "storage_access", category: "alert", first_seen_unix: now - 240, last_seen_unix: now - 240,
    data: { verdict: "denied", access_response: "kill", app_name: "Google Chrome", resource_id: "chrome", data_category: "passwords", resource_path: "/home/dev/.config/google-chrome/Default/Login Data", process_pid: 4242, process_image_path: program.image_path, actor_app: "claude-helper", actor_process: program, actor_chain: chain } },
]
const alert = alertFromRun(raws)
createRoot(document.getElementById("root")!).render(
  <div className="home-canvas notif-canvas" style={{ width: 452 }}>
    <div className="notif-fit">
      <AlertNotification alert={alert} at={(now - 240) * 1000} style="full" onClose={() => {}} onKill={() => {}} onMarkFalsePositive={() => {}} onViewDetails={() => {}} />
    </div>
  </div>,
)
